package app.loveu;
import android.content.Context;import android.graphics.*;import android.view.*;import java.time.*;import java.util.*;
final class WorkbuddyCalendarView extends View {
 final YearMonth month;final Map<String,Integer> counts;final String selected;final CalendarView.Selected listener;final Paint p=new Paint(3);final float d;final TapGesture tap;
 WorkbuddyCalendarView(Context c,YearMonth month,Map<String,Integer> counts,String selected,CalendarView.Selected listener){super(c);this.month=month;this.counts=counts;this.selected=selected;this.listener=listener;d=getResources().getDisplayMetrics().density;tap=new TapGesture(ViewConfiguration.get(c).getScaledTouchSlop());setContentDescription(month+"日历，数字表示当天记录数量");}
 static int height(YearMonth month){return 42+56*((month.atDay(1).getDayOfWeek().getValue()%7+month.lengthOfMonth()+6)/7)+12;}
 protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth()/7f;p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));p.setTextSize(13*d);p.setColor(Ui.MUTED);String[] week=Language.weekdays();for(int i=0;i<7;i++)c.drawText(Language.ui(week[i]),w*(i+.5f),22*d,p);int offset=month.atDay(1).getDayOfWeek().getValue()%7;for(int day=1;day<=month.lengthOfMonth();day++){int cell=offset+day-1;float x=w*(cell%7+.5f),y=42*d+56*d*(cell/7);String date=month.atDay(day).toString();boolean chosen=date.equals(selected),today=date.equals(LocalDate.now().toString());if(chosen){p.setColor(Ui.BERRY);c.drawRoundRect(x-20*d,y,x+20*d,y+42*d,12*d,12*d,p);}else if(today){p.setColor(Ui.BORDER);c.drawRoundRect(x-20*d,y,x+20*d,y+42*d,12*d,12*d,p);}p.setTextSize(16*d);p.setColor(chosen?Ui.ON_ACCENT:Ui.INK);c.drawText(Language.ui(""+day),x,y+16*d,p);int n=counts.getOrDefault(date,0);if(n>0){p.setTextSize(10*d);p.setColor(chosen?Ui.ON_ACCENT:Ui.BERRY);c.drawText(Language.ui(""+n),x,y+34*d,p);}}}
 public boolean onTouchEvent(MotionEvent e){if(e.getPointerCount()>1){tap.cancel();return true;}switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:tap.start(e.getX(),e.getY());break;case MotionEvent.ACTION_MOVE:tap.move(e.getX(),e.getY());break;case MotionEvent.ACTION_CANCEL:tap.cancel();break;case MotionEvent.ACTION_UP:if(tap.finish(e.getX(),e.getY())&&e.getY()>=42*d&&e.getX()>=0&&e.getX()<getWidth()){int col=(int)(e.getX()/(getWidth()/7f)),row=(int)((e.getY()-42*d)/(56*d)),day=row*7+col-(month.atDay(1).getDayOfWeek().getValue()%7)+1;if(day>=1&&day<=month.lengthOfMonth()){performClick();listener.date(month.atDay(day).toString());}}break;}return true;}
 public boolean performClick(){super.performClick();return true;}
}
